head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > repeatNode]<br/>DataList 모듈에서 XML 형식으로 데이터를 전달하거나 받을때 XML 의 데이터 노드 태그로 적용될 값을 설정합니다.",
    "validation" : [
        "반복되는 데이터 노드의 태그명을 설정합니다.",
        "속성값을 설정하지 않으면 'map' 으로 적용됩니다.",
        "DataList 모듈의 메소드에 XML 형식으로 파라미터를 전달할때 반복되는 데이터 노드의 태그명은 repeatNode 속성값으로 설정해야 합니다.",
        "DataList 모듈의 메소드에서 XML 형식의 데이터를 반환할때 repeatNode 속성값이 반복되는 데이터 노드의 태그명으로 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }  

    // 조건 설정       
    let properties = {
        repeatNode : con_repeatNode.getText(),
    };

    let cList = $c.gcm.createCList(properties);  

    // target 생성
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col2" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col3" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col4" name="name1" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_1]]></col1>';
    strTarget += '<col2><![CDATA[col2_1]]></col2>';
    strTarget += '<col3><![CDATA[col3_1]]></col3>';
    strTarget += '<col4><![CDATA[col4_1]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_2]]></col1>';
    strTarget += '<col2><![CDATA[col2_2]]></col2>';
    strTarget += '<col3><![CDATA[col3_2]]></col3>';
    strTarget += '<col4><![CDATA[col4_2]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_3]]></col1>';
    strTarget += '<col2><![CDATA[col2_3]]></col2>';
    strTarget += '<col3><![CDATA[col3_3]]></col3>';
    strTarget += '<col4><![CDATA[col4_3]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[col1_4]]></col1>';
    strTarget += '<col2><![CDATA[col2_4]]></col2>';
    strTarget += '<col3><![CDATA[col3_4]]></col3>';
    strTarget += '<col4><![CDATA[col4_4]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';    

    $p.data.create(strTarget);

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');    
}   



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = '' 

    rtn = target1.getInfo().dataListInfo.repeatNode;
    wf_body_bottom.getObj("scwin").setReturnValue("root node: " + rtn);

    rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);

};



scwin.btn_setXML_onclick = function (e) {   
    let xmlData = WebSquare.xml.parse(par_xmlData.getText());   

    target1.setXML(xmlData);

    scwin.btn_getAllJSON_onclick();
};
